(1989019, 272648, 47852, '<td valign="top">Clever idea.. love the facial expressions.  Seems a bit bright in the center, and the shadows are a bit distracting.  Clearly illustrates an "oops" with no title needed!  Good job!</td>', 'Clever idea.. love the facial expressions.  Seems a bit bright in the center, and the shadows are a bit distracting.  Clearly illustrates an "oops" with no title needed!  Good job!', '2005-12-30 18:31:21.000000', NULL, 1),
(1989020, 273090, 47852, '<td valign="top">How many shots did this take?  A definate "oops" with no title needed to explain!  Flash seems to have taken over the lighting here.. wish it were more natural light.  A great job!!</td>', 'How many shots did this take?  A definate "oops" with no title needed to explain!  Flash seems to have taken over the lighting here.. wish it were more natural light.  A great job!!', '2005-12-30 18:33:35.000000', NULL, 1),
