INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1994934, 273090, 41675, '<td valign="top">E-yup, that''s an oops alright. If the lighting/flash weren''t as harsh or bright, I would have scored this another point higher. Good solid entry though in my untrained opinion.</td>', 'E-yup, that''s an oops alright. If the lighting/flash weren''t as harsh or bright, I would have scored this another point higher. Good solid entry though in my untrained opinion.', '2006-01-02 12:34:41.000000', NULL, 1),
(1994935, 272583, 41675, '<td valign="top">Your title and photo made me chuckle. Cute concept.</td>', 'Your title and photo made me chuckle. Cute concept.', '2006-01-02 12:35:06.000000', NULL, 1),
(1994941, 272631, 41675, '<td valign="top">I like their expressions and good skin tones. Unfortunately the busy background makes me see this as more of an everyday snapshot. No offense.</td>', 'I like their expressions and good skin tones. Unfortunately the busy background makes me see this as more of an everyday snapshot. No offense.', '2006-01-02 12:36:43.000000', NULL, 1),
(1994944, 272877, 41675, '<td valign="top">Well, the title makes absolutely no sense to me, must be an inside joke, I guess. Compared with other entries it doesn''t give me an "oops" kind of feeling. (Although I''m sure there are many male voters who will absolutely love seeing this).</td>', 'Well, the title makes absolutely no sense to me, must be an inside joke, I guess. Compared with other entries it doesn''t give me an "oops" kind of feeling. (Although I''m sure there are many male voters who will absolutely love seeing this).', '2006-01-02 12:38:36.000000', NULL, 1),
(1994945, 272909, 41675, '<td valign="top">Good catch and nice entry. If some of the distracting background elements weren''t there, I would have scored this a point higher. My favorite part is the droplet in the front.</td>', 'Good catch and nice entry. If some of the distracting background elements weren''t there, I would have scored this a point higher. My favorite part is the droplet in the front.', '2006-01-02 12:40:25.000000', NULL, 1),
